changeSet.sql:
UPDATE REFDATA.TM_INTERVAL SET PERIOD_LENGTH = INTERVAL '1 day'
 WHERE TM_INTERVAL_ID = 1 AND PERIOD_LENGTH IS NULL;

UPDATE REFDATA.TM_INTERVAL SET PERIOD_LENGTH = INTERVAL '1 hour'
 WHERE TM_INTERVAL_ID = 2 AND PERIOD_LENGTH IS NULL;

ALTER TABLE REFDATA.TM_INTERVAL
    ALTER COLUMN PERIOD_LENGTH SET NOT NULL;
